// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock reports the current time. It is an injection point for tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
// The zero value is not usable; construct with New.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	capacity float64
	rate     float64 // tokens per second
	clock    Clock
}

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). Both must be > 0.
func New(burst int, ratePerSec float64, clock Clock) (*Limiter, error) {
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if ratePerSec <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens:   float64(burst),
		capacity: float64(burst),
		rate:     ratePerSec,
		clock:    clock,
	}, nil
}

// refill advances the bucket to time now, adding accrued tokens.
// Caller must hold l.mu.
func (l *Limiter) refill(now time.Time) {
	if elapsed := now.Sub(l.last); elapsed > 0 {
		l.tokens += elapsed.Seconds() * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
	}
	l.last = now
}

// AllowN reports whether n tokens may be consumed at time now,
// without consuming them.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	if float64(n) <= l.tokens {
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now, without consuming it.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// TakeN consumes n tokens at time now if available, reporting success.
func (l *Limiter) TakeN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Take consumes one token at the current clock time if available.
func (l *Limiter) Take() bool {
	return l.TakeN(l.clock.Now(), 1)
}
