package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	t time.Time
}

func (f *fakeClock) Now() time.Time { return f.t }

func (f *fakeClock) advance(d time.Duration) { f.t = f.t.Add(d) }

func mustNew(t *testing.T, burst int, rate float64, c Clock) *Limiter {
	t.Helper()
	l, err := New(burst, rate, c)
	if err != nil {
		t.Fatalf("New(%d, %v) error: %v", burst, rate, err)
	}
	return l
}

func TestNewValidation(t *testing.T) {
	cases := []struct {
		name  string
		burst int
		rate  float64
		ok    bool
	}{
		{"valid", 1, 1, true},
		{"zero burst", 0, 1, false},
		{"negative burst", -1, 1, false},
		{"zero rate", 1, 0, false},
		{"negative rate", 1, -0.5, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.burst, tc.rate, &fakeClock{})
			if tc.ok != (err == nil) {
				t.Fatalf("New(%d, %v) err = %v, want ok=%v", tc.burst, tc.rate, err, tc.ok)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	cases := []struct {
		name    string
		burst   int
		rate    float64
		steps   []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst exhausted then refills",
			burst: 2, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, true},
				{0, 1, false},
				{time.Second, 1, true},
				{0, 1, false},
				{2 * time.Second, 2, true},
			},
		},
		{
			name: "burst larger than single request",
			burst: 5, rate: 0.5,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, true},
				{0, 3, false},
				{4 * time.Second, 2, true},
				{0, 1, false},
			},
		},
		{
			name: "no negative tokens",
			burst: 1, rate: 10,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 5, false},
				{time.Second, 1, true},
			},
		},
		{
			name: "zero tokens allowed",
			burst: 1, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true},
				{0, 0, true},
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clk := &fakeClock{t: base}
			l := mustNew(t, tc.burst, tc.rate, clk)
			for i, s := range tc.steps {
				clk.advance(s.advance)
				if got := l.AllowN(clk.t, s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%v, %d) = %v, want %v", i, clk.t, s.n, got, s.want)
				}
			}
		})
	}
}

func TestTakeNConsumes(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	l := mustNew(t, 2, 1, clk)
	if !l.TakeN(clk.t, 2) {
		t.Fatal("TakeN(2) = false, want true")
	}
	if l.TakeN(clk.t, 1) {
		t.Fatal("TakeN(1) after drain = true, want false")
	}
	if !l.AllowN(clk.t, 1) {
		t.Fatal("AllowN must not consume tokens")
	}
	if l.TakeN(clk.t, 1) {
		t.Fatal("TakeN after AllowN = true, want false")
	}
}

func TestConcurrentUse(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	l := mustNew(t, 100, 1000, clk)
	var wg sync.WaitGroup
	var mu sync.Mutex
	granted := 0
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				if l.TakeN(clk.t, 1) {
					mu.Lock()
					granted++
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	if granted != 100 {
		t.Fatalf("granted = %d, want 100", granted)
	}
}
