package ratelimit

import (
	"sync"
	"testing"
	"time"
)

// fakeClock is a manually advanced clock.
type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock(start time.Time) *fakeClock { return &fakeClock{now: start} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewLimiterValidation(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  error
	}{
		{"zero capacity", 0, 1, clock, ErrNonPositiveCapacity},
		{"negative capacity", -1, 1, clock, ErrNonPositiveCapacity},
		{"zero rate", 1, 0, clock, ErrNonPositiveRate},
		{"negative rate", 1, -0.5, clock, ErrNonPositiveRate},
		{"nil clock", 1, 1, nil, ErrNilClock},
		{"valid", 10, 2.5, clock, nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := NewLimiter(tc.capacity, tc.rate, tc.clock)
			if tc.wantErr != nil {
				if err != tc.wantErr {
					t.Fatalf("got err %v, want %v", err, tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if l.capacity != float64(tc.capacity) || l.rate != tc.rate {
				t.Fatalf("limiter misconfigured: %+v", l)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)

	tests := []struct {
		name     string
		capacity int
		rate     float64
		steps    []struct {
			advance time.Duration // before the call
			n       int
			want    bool
		}
	}{
		{
			name: "burst up to capacity then denied",
			capacity: 3, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, true},
				{0, 1, true},
				{0, 1, false},
			},
		},
		{
			name: "refill over time",
			capacity: 2, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{0, 1, false},
				{time.Second, 1, true},
				{0, 1, false},
				{500 * time.Millisecond, 1, false}, // only 0.5 tokens accrued
				{500 * time.Millisecond, 1, true},
			},
		},
		{
			name: "tokens cap at capacity",
			capacity: 1, rate: 10,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{time.Hour, 2, false}, // still capped at 1
				{0, 1, true},
			},
		},
		{
			name: "zero and negative requests",
			capacity: 1, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true},
				{0, -1, false},
				{0, 1, true},
			},
		},
		{
			name: "fractional refill accumulates",
			capacity: 1, rate: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{100 * time.Millisecond, 1, false},
				{100 * time.Millisecond, 1, false},
				{100 * time.Millisecond, 1, false},
				{100 * time.Millisecond, 1, false},
				{100 * time.Millisecond, 1, true}, // 1.0 tokens after 500ms at 2/s
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock(base)
			l, err := NewLimiter(tc.capacity, tc.rate, clock)
			if err != nil {
				t.Fatalf("NewLimiter: %v", err)
			}
			for i, s := range tc.steps {
				clock.Advance(s.advance)
				if got := l.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestConcurrentUse(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, err := NewLimiter(100, 1000, clock)
	if err != nil {
		t.Fatalf("NewLimiter: %v", err)
	}
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				if l.Allow() {
					mu.Lock()
					allowed++
					mu.Unlock()
				}
				clock.Advance(time.Millisecond)
			}
		}()
	}
	wg.Wait()
	if allowed > 100 {
		t.Fatalf("allowed %d requests, capacity is 100", allowed)
	}
}

func TestTokensRefill(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, err := NewLimiter(5, 1, clock)
	if err != nil {
		t.Fatalf("NewLimiter: %v", err)
	}
	l.AllowN(5)
	if got := l.Tokens(); got != 0 {
		t.Fatalf("Tokens() = %v, want 0", got)
	}
	clock.Advance(2500 * time.Millisecond)
	if got := l.Tokens(); got != 2.5 {
		t.Fatalf("Tokens() = %v, want 2.5", got)
	}
}
